    static final String ENV="buildupmobtweaks:r4e3c",ARENA=SkeletonBehaviorTests.ARENA;
    static <T extends Mob>T mob(GameTestHelper h,EntityType<T> t,int x,int z){return RidingRelationTests.mob(h,t,x,z);}
    static void floor(GameTestHelper h){SkeletonBehaviorTests.floor(h,true);}
    static void proof(String s,Mob m,String d){BuildupMobTweaks.LOGGER.info("R4E3C_PROOF {} ticks={} uuid={} {}",s,m.tickCount,m.getUUID(),d);}
    void pumpkin(GameTestHelper h,String mode){floor(h);var s=mob(h,EntityTypes.SNOW_GOLEM,8,8);s.setNoAi(true);s.setItemSlot(EquipmentSlot.HEAD,ItemStack.EMPTY);var f=SkeletonBehaviorTests.player(h);var p=f.player();p.snapTo(s.position().add(0,0,2),0,0);
        var outside=BuildupMobTweaks.id("test_external_armor");s.getAttribute(Attributes.ARMOR).setBaseValue(3);s.getAttribute(Attributes.ARMOR).addTransientModifier(new AttributeModifier(outside,2,AttributeModifier.Operation.ADD_VALUE));
        h.runAtTickTime(5,()->{h.assertTrue(s.getArmorValue()==15,"Conditional 10 armor preserves external base and modifier");p.setItemInHand(InteractionHand.MAIN_HAND,Items.SHEARS.getDefaultInstance());s.interact(p,InteractionHand.MAIN_HAND,net.minecraft.world.phys.Vec3.ZERO);});
        h.runAtTickTime(8,()->{h.assertTrue(!s.hasPumpkin()&&s.getArmorValue()==5,"Native shear removes only owned modifier");h.assertTrue(h.getLevel().getEntitiesOfClass(ItemEntity.class,s.getBoundingBox().inflate(8),e->e.getItem().is(Items.CARVED_PUMPKIN)).stream().mapToInt(e->e.getItem().getCount()).sum()==1,"Actual native shearing loot exactly one");
            if(mode.equals("creative"))p.setGameMode(GameType.CREATIVE);if(mode.equals("off"))s.addTag("buildupmobtweaks:disable_snow_golem_pumpkin_return");p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.CARVED_PUMPKIN,3));s.interact(p,InteractionHand.MAIN_HAND,net.minecraft.world.phys.Vec3.ZERO);s.interact(p,InteractionHand.MAIN_HAND,net.minecraft.world.phys.Vec3.ZERO);});
        h.runAtTickTime(11,()->{h.assertTrue(s.hasPumpkin()!=mode.equals("off"),"Return obeys independent gate");h.assertTrue(p.getMainHandItem().getCount()==(mode.equals("normal")?2:3),"Survival consumes exactly one, repeat/creative/disabled consume none");s.addTag("buildupmobtweaks:disable_snow_golem_pumpkin_defense");});
        h.runAtTickTime(14,()->{h.assertTrue(s.getArmorValue()==5,"Defense gate leaves external armor");proof("pumpkin_"+mode,s,"armor="+s.getArmorValue()+" count="+p.getMainHandItem().getCount());s.discard();f.close();h.succeed();});}
