    void snow(GameTestHelper h,String mode){floor(h);var s=mob(h,EntityTypes.SNOW_GOLEM,8,8);s.setPumpkin(false);s.getRandom().setSeed(98651);s.getAttribute(Attributes.MOVEMENT_SPEED).setBaseValue(0);var t=mob(h,EntityTypes.BLAZE,8,16);t.setNoAi(true);t.setNoGravity(true);
        if(mode.equals("off"))s.addTag("buildupmobtweaks:vanilla_ai");if(mode.equals("visual_off"))s.addTag("buildupmobtweaks:disable_snow_golem_throw_visual");if(mode.equals("ranged_off"))s.addTag("buildupmobtweaks:disable_snow_golem_ranged_behavior");
        Set<UUID> ids=new HashSet<>();List<Long> times=new ArrayList<>();boolean[] prepared={false};
        h.onEachTick(()->{prepared[0]|=s.getAttachedOrCreate(AbilityState.THROW)>4;for(var b:h.getLevel().getEntitiesOfClass(Snowball.class,s.getBoundingBox().inflate(30),e->e.getOwner()==s))if(ids.add(b.getUUID()))times.add(h.getLevel().getGameTime());});
        h.runAtTickTime(210,()->{var r=AbilityState.runtime(s);proof("snow_"+mode,s,"balls="+ids.size()+" times="+times+" targetHP="+t.getHealth()+" windup="+prepared[0]+" goals="+s.getGoalSelector().getAvailableGoals().stream().filter(g->g.isRunning()).map(g->g.getGoal().getClass().getSimpleName()).toList());
            h.assertTrue(s.getTarget()==t&&ids.size()>=5,"Actual native target acquisition and projectile flight");h.assertTrue(prepared[0]==(!mode.equals("off")&&!mode.equals("visual_off")),"Independent actual animation preparation");
            if(!mode.equals("off")&&!mode.equals("ranged_off")){h.assertTrue(ids.size()>=14&&t.getHealth()<1000,"Adapted native Goal cadence and actual Blaze snowball damage");h.assertTrue(r.released==ids.size(),"One entity per release, no passenger copies");}else h.assertTrue(ids.size()<=11,"Original 20 tick cadence restored");
            for(int i=1;i<times.size();i++)h.assertTrue(times.get(i)-times.get(i-1)>=(mode.equals("off")||mode.equals("ranged_off")?20:10),"No double release");RidingRelationTests.clean(s,t);h.succeed();});}
