    void cancel(GameTestHelper h,String mode){floor(h);SnowGolem[] ref={mob(h,EntityTypes.SNOW_GOLEM,8,8)};ref[0].getRandom().setSeed(98651);ref[0].getAttribute(Attributes.MOVEMENT_SPEED).setBaseValue(0);var t=mob(h,EntityTypes.BLAZE,8,16);t.setNoAi(true);boolean[] triggered={false};int[] at={0};
        h.onEachTick(()->{var s=ref[0];if(!triggered[0]&&AbilityState.runtime(s).target!=null){triggered[0]=true;at[0]=AbilityState.runtime(s).released;proof("snow_cancel_input_"+mode,s,"preparedTarget="+AbilityState.runtime(s).target.getUUID()+" fixture="+t.getUUID());
            switch(mode){case "noai"->s.setNoAi(true);case "death"->s.setHealth(0);case "off"->s.addTag("buildupmobtweaks:vanilla_ai");case "target"->t.discard();case "wall"->{for(int x=4;x<=12;x++)for(int y=2;y<=6;y++)h.setBlock(new BlockPos(x,y,12),Blocks.STONE);}case "reload"->{ref[0]=CombatTestWorld.reload(h,s);ref[0].setNoAi(true);}}
        }});
        h.runAtTickTime(70,()->{var s=ref[0];proof("snow_cancel_observed_"+mode,s,"triggered="+triggered[0]+" preparedTarget="+(AbilityState.runtime(s).target==null?"none":AbilityState.runtime(s).target.getUUID())+" fixtureRemoved="+t.isRemoved()+" animation="+s.getAttachedOrCreate(AbilityState.THROW)+" released="+AbilityState.runtime(s).released+" initialReleased="+at[0]);h.assertTrue(triggered[0]&&AbilityState.runtime(s).target==null&&s.getAttachedOrCreate(AbilityState.THROW)==0,"Actual boundary cancels preparation");h.assertTrue(AbilityState.runtime(s).released==at[0],"No aborted or reloaded preparation releases a ball");proof("snow_cancel_"+mode,s,"released="+AbilityState.runtime(s).released);RidingRelationTests.clean(s,t);h.succeed();});}
