    @GameTest(environment=ENV,structure=ARENA,maxTicks=120) public void snowBoundedRetaliationSweep(GameTestHelper h){floor(h);var s=mob(h,EntityTypes.SNOW_GOLEM,8,8);s.getAttribute(Attributes.MOVEMENT_SPEED).setBaseValue(0);List<Mob> targets=new ArrayList<>();for(int i=0;i<8;i++){var t=mob(h,EntityTypes.ZOMBIE,5+i,15);t.setNoAi(true);t.setTarget(s);targets.add(t);}int[] peak={0};h.onEachTick(()->{peak[0]=Math.max(peak[0],AbilityState.runtime(s).released);});
        h.runAtTickTime(85,()->{h.assertTrue(AbilityState.runtime(s).scans==1&&peak[0]>=3&&peak[0]<=8,"One bounded scan/sweep then native ordinary shots, never unbounded per-tick barrage");proof("snow_sweep",s,"scans="+AbilityState.runtime(s).scans+" releases="+peak[0]);s.discard();targets.forEach(Entity::discard);h.succeed();});}
    static AbstractSkeleton born(GameTestHelper h,EntityType<? extends AbstractSkeleton> type,EntitySpawnReason reason,long seed){var m=type.create(h.getLevel(),reason);m.getRandom().setSeed(seed);m.finalizeSpawn(h.getLevel(),h.getLevel().getCurrentDifficultyAt(h.absolutePos(new BlockPos(8,2,8))),reason,null);return m;}
    @GameTest(environment=ENV,structure=ARENA,maxTicks=20) public void babyBirthDistributionNativeFinalize(GameTestHelper h){int count=0;int n=1000;for(int i=0;i<n;i++){var s=born(h,EntityTypes.SKELETON,EntitySpawnReason.SPAWN_ITEM_USE,900000+i);if(s.isBaby())count++;}
        var actor=mob(h,EntityTypes.SKELETON,8,8);proof("baby_birth_N1000",actor,"selected="+count+" tolerance=65..135 default=100/1000");h.assertTrue(count>=65&&count<=135,"Predeclared binomial tolerance on actual finalization, no forced probability");actor.discard();h.succeed();}
    void baby(GameTestHelper h,EntityType<? extends AbstractSkeleton> type){floor(h);var s=type.create(h.getLevel(),EntitySpawnReason.COMMAND);var d=new CompoundTag();d.putInt("version",1);d.putBoolean("baby_choice",true);s.setAttached(AbilityState.DATA,d);s.snapTo(h.absolutePos(new BlockPos(8,2,8)),0,0);s.setPersistenceRequired();s.setItemSlot(EquipmentSlot.MAINHAND,Items.IRON_SWORD.getDefaultInstance());s.setItemSlot(EquipmentSlot.HEAD,Items.IRON_HELMET.getDefaultInstance());h.getLevel().addFreshEntity(s);AbstractSkeleton[] ref={s};float[] width={0},height={0};
        h.runAtTickTime(8,()->{h.assertTrue(s.isBaby()&&s.getBbWidth()<.5&&s.getEyeHeight()<1.1,"Synced baby changes native physical width and eye height");width[0]=s.getBbWidth();height[0]=s.getBbHeight();ref[0]=CombatTestWorld.reload(h,s);});
        h.runAtTickTime(12,()->{h.assertTrue(ref[0].isBaby()&&ref[0].getBbWidth()==width[0]&&ref[0].getBbHeight()==height[0],"Real save/load preserves selection and physical dimensions");ref[0].addTag("buildupmobtweaks:disable_skeleton_baby_variant");});
        h.runAtTickTime(16,()->{h.assertTrue(!ref[0].isBaby()&&Math.abs(ref[0].getBbWidth()-2*width[0])<.001,"Live disable restores native adult size");ref[0].removeTag("buildupmobtweaks:disable_skeleton_baby_variant");});
        h.runAtTickTime(20,()->{h.assertTrue(ref[0].isBaby()&&ref[0].getMainHandItem().is(Items.IRON_SWORD)&&ref[0].getItemBySlot(EquipmentSlot.HEAD).is(Items.IRON_HELMET),"Reenable does not reroll or replace equipment");proof("baby_"+type,ref[0],"width="+ref[0].getBbWidth()+" eye="+ref[0].getEyeHeight());ref[0].discard();h.succeed();});}
