    @GameTest(environment=ENV,structure=ARENA,maxTicks=25) public void unknownAbilityDataUntouchedAndNoBirthReroll(GameTestHelper h){floor(h);var s=EntityTypes.SKELETON.create(h.getLevel(),EntitySpawnReason.SPAWN_ITEM_USE);var d=new CompoundTag();d.putInt("version",99);d.putBoolean("baby_choice",true);d.putString("future","opaque");s.setAttached(AbilityState.DATA,d);s.finalizeSpawn(h.getLevel(),h.getLevel().getCurrentDifficultyAt(h.absolutePos(new BlockPos(8,2,8))),EntitySpawnReason.SPAWN_ITEM_USE,null);s.snapTo(h.absolutePos(new BlockPos(8,2,8)),0,0);h.getLevel().addFreshEntity(s);
        h.runAtTickTime(10,()->{h.assertTrue(d.equals(s.getAttached(AbilityState.DATA))&&!s.isBaby(),"Unknown version opaque/native fallback");s.discard();h.succeed();});}
    void breeze(GameTestHelper h,String mode){floor(h);var b=mob(h,EntityTypes.BREEZE,8,8);var f=SkeletonBehaviorTests.player(h);f.player().snapTo(b.position().add(0,0,7),0,0);if(mode.equals("off"))b.addTag("buildupmobtweaks:disable_breeze_shotgun");
        Set<UUID> seen=new HashSet<>();List<Long> volleys=new ArrayList<>();int[] last={0};boolean[] hit={false};
        h.onEachTick(()->{for(var p:h.getLevel().getEntitiesOfClass(BreezeWindCharge.class,b.getBoundingBox().inflate(45),p->p.getOwner()==b))seen.add(p.getUUID());var r=AbilityState.runtime(b);hit[0]|=f.player().getHealth()<20;
            if(r.volleys>last[0]){last[0]=r.volleys;volleys.add(h.getLevel().getGameTime());}
        });
        h.runAtTickTime(360,()->{var r=AbilityState.runtime(b);proof("breeze_"+mode,b,"seen="+seen.size()+" volleys="+volleys+" extra="+r.extra+" hit="+hit[0]);h.assertTrue(seen.size()>0,"Native Brain creates real wind charge");h.assertTrue(mode.equals("off")?r.extra==0:r.extra==2*r.volleys&&r.volleys>0,"Only bounded two extra native projectiles per approved volley");for(int i=1;i<volleys.size();i++)h.assertTrue(volleys.get(i)-volleys.get(i-1)>=100,"Actual native volleys share saved 100 tick window");b.discard();f.close();h.succeed();});}
