    @GameTest(environment=ENV,structure=ARENA,maxTicks=80) public void babyFatalNativeConversionPreservesChoiceAndGear(GameTestHelper h){floor(h);var m=mob(h,EntityTypes.SKELETON,8,8);m.getAttached(AbilityState.DATA).putBoolean("baby_choice",true);m.setItemSlot(EquipmentSlot.MAINHAND,new ItemStack(Items.IRON_AXE));m.getMainHandItem().setDamageValue(11);var killer=mob(h,EntityTypes.WITHER_SKELETON,8,15);killer.setNoAi(true);
        h.runAtTickTime(10,()->m.hurtServer(h.getLevel(),m.damageSources().mobAttack(killer),2000));
        h.runAtTickTime(35,()->{var list=h.getLevel().getEntitiesOfClass(net.minecraft.world.entity.monster.skeleton.WitherSkeleton.class,m.getBoundingBox().inflate(4),w->w!=killer);h.assertTrue(m.isRemoved()&&list.size()==1,"Native lethal conversion exactly once");var w=list.getFirst();h.assertTrue(w.isBaby()&&w.getAttached(AbilityState.DATA).getBooleanOr("baby_choice",false)&&w.getMainHandItem().is(Items.IRON_AXE)&&w.getMainHandItem().getDamageValue()==11,"Choice and real gear survive conversion, no reroll");h.assertTrue(h.getLevel().getEntitiesOfClass(ItemEntity.class,m.getBoundingBox().inflate(4)).isEmpty(),"No duplicated rewards");RidingRelationTests.clean(w,killer);h.succeed();});}
    @GameTest(environment=ENV,structure=ARENA,maxTicks=230) public void babyNoAiNoGrowthAndNoLoadReroll(GameTestHelper h){floor(h);var s=mob(h,EntityTypes.SKELETON,8,8);s.getAttached(AbilityState.DATA).putBoolean("baby_choice",true);s.setNoAi(true);
        h.runAtTickTime(200,()->{h.assertTrue(s.isBaby()&&s.getBbWidth()==.3f,"NoAI does not erase physical baby choice; no growth timer");var loaded=CombatTestWorld.reload(h,s);h.assertTrue(loaded.isBaby(),"Load applies saved choice synchronously");loaded.discard();h.succeed();});}
    @GameTest(environment=ENV,structure=ARENA,maxTicks=25) public void birthSourcesAndRepeatedFinalizationDoNotReroll(GameTestHelper h){
        for(var reason:List.of(EntitySpawnReason.NATURAL,EntitySpawnReason.CHUNK_GENERATION,EntitySpawnReason.SPAWN_ITEM_USE,EntitySpawnReason.SPAWNER,EntitySpawnReason.TRIAL_SPAWNER,EntitySpawnReason.COMMAND,EntitySpawnReason.CONVERSION)){var s=born(h,EntityTypes.STRAY,reason,70001);var d=s.getAttached(AbilityState.DATA).copy();s.finalizeSpawn(h.getLevel(),h.getLevel().getCurrentDifficultyAt(h.absolutePos(new BlockPos(8,2,8))),reason,null);h.assertTrue(d.equals(s.getAttached(AbilityState.DATA)),"Birth choice is immutable on repeated finalization");if(reason==EntitySpawnReason.COMMAND||reason==EntitySpawnReason.CONVERSION)h.assertTrue(!s.isBaby(),"Skipped source remains adult");}h.succeed();}
    void playerExit(GameTestHelper h,GameType type){floor(h);var s=mob(h,EntityTypes.SNOW_GOLEM,8,8);s.getAttribute(Attributes.MOVEMENT_SPEED).setBaseValue(0);var f=SkeletonBehaviorTests.player(h);f.player().snapTo(s.position().add(0,0,6),0,0);s.setTarget(f.player());boolean[] triggered={false};
        h.onEachTick(()->{if(!triggered[0]&&AbilityState.runtime(s).target!=null){triggered[0]=true;f.player().setGameMode(type);}});
        h.runAtTickTime(65,()->{h.assertTrue(triggered[0]&&s.getTarget()==null&&AbilityState.runtime(s).released==0&&s.getAttachedOrCreate(AbilityState.THROW)==0,"Actual mode change exits target and aborts windup");s.discard();f.close();h.succeed();});}
