    @GameTest(environment=ENV,structure=ARENA,maxTicks=180) public void snowLiveGateRestoresOnlyOriginalGoal(GameTestHelper h){floor(h);var s=mob(h,EntityTypes.SNOW_GOLEM,8,8);s.getAttribute(Attributes.MOVEMENT_SPEED).setBaseValue(0);var t=mob(h,EntityTypes.BLAZE,8,16);t.setNoAi(true);Set<UUID> ids=new HashSet<>();List<Long> times=new ArrayList<>();
        h.onEachTick(()->{for(var ball:h.getLevel().getEntitiesOfClass(Snowball.class,s.getBoundingBox().inflate(30),p->p.getOwner()==s))if(ids.add(ball.getUUID())&&s.tickCount>=100)times.add(h.getLevel().getGameTime());});
        h.runAtTickTime(75,()->s.addTag("buildupmobtweaks:vanilla_ai"));h.runAtTickTime(160,()->{h.assertTrue(!AbilityState.runtime(s).managed&&s.getGoalSelector().getAvailableGoals().stream().filter(g->g.getGoal() instanceof net.minecraft.world.entity.ai.goal.RangedAttackGoal).count()==1,"Live disable restores sole original attack Goal");h.assertTrue(times.size()>=2,"Original Goal resumes firing");for(int i=1;i<times.size();i++)h.assertTrue(times.get(i)-times.get(i-1)>=20,"Original cadence after live disable");RidingRelationTests.clean(s,t);h.succeed();});}
    @GameTest(environment="buildupmobtweaks:r4e3c_config",structure=ARENA,maxTicks=30) public void realGlobalAndIndependentPhysicalGates(GameTestHelper h){floor(h);var cfg=BuildupMobTweaks.config();boolean master=cfg.general.enabled.get(),armor=cfg.passive.snow_golem_pumpkin_defense.get();var s=mob(h,EntityTypes.SNOW_GOLEM,8,8);s.setItemSlot(EquipmentSlot.HEAD,ItemStack.EMPTY);var k=mob(h,EntityTypes.SKELETON,12,8);k.getAttached(AbilityState.DATA).putBoolean("baby_choice",true);
        h.runAtTickTime(5,()->{h.assertTrue(k.isBaby()&&s.getArmorValue()==10,"Defaults are effective");cfg.passive.snow_golem_pumpkin_defense.setAndUpdate(false);});
        h.runAtTickTime(9,()->{h.assertTrue(k.isBaby()&&s.getArmorValue()==0,"Independent config leaves unrelated physical variant");cfg.general.enabled.setAndUpdate(false);});
        h.runAtTickTime(13,()->{h.assertTrue(!k.isBaby()&&s.getArmorValue()==0,"Actual general gate restores native physical state");cfg.general.enabled.setAndUpdate(master);cfg.passive.snow_golem_pumpkin_defense.setAndUpdate(armor);});
        h.runAtTickTime(18,()->{try{h.assertTrue(k.isBaby()&&s.getArmorValue()==10,"Config reenable uses saved choice, no reroll");h.succeed();}finally{cfg.general.enabled.setAndUpdate(master);cfg.passive.snow_golem_pumpkin_defense.setAndUpdate(armor);RidingRelationTests.clean(s,k);}});}
    @GameTest(environment=ENV,structure=ARENA,maxTicks=300) public void breezeRealAnglesHitAndReloadBudget(GameTestHelper h){floor(h);Breeze[] actor={mob(h,EntityTypes.BREEZE,8,8)};var f=SkeletonBehaviorTests.player(h);f.player().snapTo(actor[0].position().add(0,0,7),0,0);f.player().getAttribute(Attributes.MAX_HEALTH).setBaseValue(1000);f.player().setHealth(1000);boolean[] observed={false},hit={false};long[] ready={0};BreezeWindCharge[] loadedBall={null};
        h.onEachTick(()->{var b=actor[0];hit[0]|=f.player().getHealth()<1000;if(!observed[0]&&AbilityState.runtime(b).extra==2){var all=h.getLevel().getEntitiesOfClass(BreezeWindCharge.class,b.getBoundingBox().inflate(30),p->p.getOwner()==b);var center=all.stream().filter(p->!AbilityState.known(p)).findFirst().orElseThrow();var extra=all.stream().filter(AbilityState::known).toList();h.assertTrue(extra.size()==2,"Three real native charges in one volley");
                var v=center.getDeltaMovement();for(var p:extra){double cosine=(v.x*p.getDeltaMovement().x+v.z*p.getDeltaMovement().z)/Math.sqrt((v.x*v.x+v.z*v.z)*(p.getDeltaMovement().x*p.getDeltaMovement().x+p.getDeltaMovement().z*p.getDeltaMovement().z));h.assertTrue(Math.abs(cosine-Math.cos(Math.toRadians(20)))<.00001,"Real +/-20 degree horizontal spread");h.assertTrue(Math.abs(v.length()-p.getDeltaMovement().length())<.00001,"Native speed conserved");}
                ready[0]=b.getAttached(RemainingState.DATA).getLongOr("breeze_special_ready",0);observed[0]=true;loadedBall[0]=CombatTestWorld.reload(h,extra.getFirst());actor[0]=CombatTestWorld.reload(h,b);actor[0].setNoAi(true);
            }});
        h.runAtTickTime(130,()->{h.assertTrue(observed[0]&&loadedBall[0].isRemoved()&&actor[0].getAttached(RemainingState.DATA).getLongOr("breeze_special_ready",0)==ready[0]&&AbilityState.runtime(actor[0]).extra==0,"Reload retires only extra flight and preserves shared budget, no action replay");actor[0].setNoAi(false);});
        h.runAtTickTime(270,()->{proof("breeze_angles_reload",actor[0],"actualHit="+hit[0]+" ready="+ready[0]+" extra="+AbilityState.runtime(actor[0]).extra);h.assertTrue(hit[0]&&AbilityState.runtime(actor[0]).extra>0,"Native middle actually hits and Brain resumes after reload");actor[0].discard();f.close();h.succeed();});}
    @GameTest(environment=ENV,structure=ARENA,maxTicks=100) public void independentQaRefusesOverlapAndCleansExactTerrain(GameTestHelper h){var o=h.absolutePos(new BlockPos(8,16,8));var scenes=com.davidblackcn.buildupmobtweaks.qa.E3cQa.SCENES;for(int i=0;i<scenes.size();i++){int at=i*12+1;var name=scenes.get(i);h.runAtTickTime(at,()->{var s=com.davidblackcn.buildupmobtweaks.qa.E3cQa.spawn(h.getLevel(),o,name);boolean refused=false;try{com.davidblackcn.buildupmobtweaks.qa.E3bQa.spawn(h.getLevel(),o,"chicken_escape",null);}catch(IllegalStateException ex){refused=true;}h.assertTrue(refused,"Cross-group one-session boundary");});h.runAtTickTime(at+8,()->{com.davidblackcn.buildupmobtweaks.qa.E3cQa.cleanup(h.getLevel().getServer());h.assertTrue(h.getLevel().getBlockState(o.below()).isAir()&&h.getLevel().getBlockState(o.above(6)).isAir(),"Exact prior air floor and roof restored");h.assertTrue(h.getLevel().getEntitiesOfClass(Mob.class,new net.minecraft.world.phys.AABB(o).inflate(24),m->m.entityTags().contains(com.davidblackcn.buildupmobtweaks.qa.QaHarness.TAG)).isEmpty(),"Own QA actors retired");});}h.runAtTickTime(85,h::succeed);}
    @GameTest(environment="buildupmobtweaks:r4e3c_hard",structure=ARENA,maxTicks=760) public void actualHardBrainShotgunJumpAndLandingShareBudget(GameTestHelper h){SkeletonBehaviorTests.floor(h,false);var server=h.getLevel().getServer();var previous=h.getLevel().getDifficulty();server.setDifficulty(net.minecraft.world.Difficulty.HARD,true);var b=mob(h,EntityTypes.BREEZE,8,8);b.getRandom().setSeed(923200);var f=SkeletonBehaviorTests.player(h);f.player().getAttribute(Attributes.MAX_HEALTH).setBaseValue(1000);f.player().setHealth(1000);boolean[] jump={false};List<Long> times=new ArrayList<>();List<String> kinds=new ArrayList<>();int[] last={0};
        h.onEachTick(()->{jump[0]|=b.getPose()==Pose.LONG_JUMPING;int count=AbilityState.runtime(b).volleys+RemainingState.runtime(b).bursts;if(count!=last[0]){h.assertTrue(count==last[0]+1,"Never two approved special events in one native tick");last[0]=count;times.add(h.getLevel().getGameTime());kinds.add(b.getPose().toString());}});
        h.runAtTickTime(720,()->{try{proof("breeze_hard_shared",b,"jump="+jump[0]+" times="+times+" kinds="+kinds+" volleys="+AbilityState.runtime(b).volleys+" bursts="+RemainingState.runtime(b).bursts);h.assertTrue(jump[0]&&times.size()>=3,"Real native Brain movement and multiple approved events");for(int i=1;i<times.size();i++)h.assertTrue(times.get(i)-times.get(i-1)>=100,"Actual shot/jump/land mutual exclusion");h.succeed();}finally{b.discard();f.close();server.setDifficulty(previous,true);}});}
    void extraFlight(GameTestHelper h,String mode){floor(h);var b=mob(h,EntityTypes.BREEZE,8,8);var f=SkeletonBehaviorTests.player(h);f.player().snapTo(b.position().add(0,0,7),0,0);BreezeWindCharge[] extra={null};boolean[] captured={false};
        h.onEachTick(()->{if(!captured[0]&&AbilityState.runtime(b).extra==2){captured[0]=true;extra[0]=h.getLevel().getEntitiesOfClass(BreezeWindCharge.class,b.getBoundingBox().inflate(30),AbilityState::known).getFirst();
            if(mode.equals("ttl")){extra[0].setPos(b.position().add(0,3,0));extra[0].setDeltaMovement(0,0,0);}else if(mode.equals("noai"))b.setNoAi(true);else if(mode.equals("off"))b.addTag("buildupmobtweaks:disable_breeze_shotgun");else {f.player().setGameMode(mode.equals("creative")?GameType.CREATIVE:GameType.SPECTATOR);}
        }});
        h.runAtTickTime(190,()->{h.assertTrue(captured[0]&&extra[0].isRemoved(),"Extra flight retires through actual native Tick at lifetime/NoAI/gate/player exit");b.discard();f.close();h.succeed();});}
