    @GameTest(environment="buildupmobtweaks:r4e3c_grief",structure=ARENA,maxTicks=155) public void extraRealWindCollisionRespectsGriefingFalse(GameTestHelper h){floor(h);var rules=h.getLevel().getGameRules();var server=h.getLevel().getServer();boolean previous=rules.get(net.minecraft.world.level.gamerules.GameRules.MOB_GRIEFING);rules.set(net.minecraft.world.level.gamerules.GameRules.MOB_GRIEFING,false,server);var b=mob(h,EntityTypes.BREEZE,8,8);var f=SkeletonBehaviorTests.player(h);f.player().snapTo(b.position().add(0,0,7),0,0);h.setBlock(new BlockPos(16,2,8),Blocks.STONE);h.setBlock(new BlockPos(16,3,8),Blocks.LEVER);BreezeWindCharge[] extra={null};
        h.onEachTick(()->{if(extra[0]==null&&AbilityState.runtime(b).extra>0){extra[0]=h.getLevel().getEntitiesOfClass(BreezeWindCharge.class,b.getBoundingBox().inflate(30),AbilityState::known).getFirst();extra[0].setPos(net.minecraft.world.phys.Vec3.atCenterOf(h.absolutePos(new BlockPos(16,2,6))));extra[0].setDeltaMovement(0,0,.7);}});
        h.runAtTickTime(125,()->{try{h.assertTrue(extra[0]!=null&&extra[0].isRemoved()&&extra[0].tickCount<20,"Real extra wind projectile hits nearby native stone collision before TTL");h.assertTrue(!h.getBlockState(new BlockPos(16,3,8)).getValue(net.minecraft.world.level.block.LeverBlock.POWERED),"Extra explosion cannot trigger lever with mobGriefing=false; original middle semantics unchanged");h.succeed();}finally{rules.set(net.minecraft.world.level.gamerules.GameRules.MOB_GRIEFING,previous,server);b.discard();f.close();}});}
    @GameTest(environment=ENV,structure=ARENA,maxTicks=230) public void actualBabyBowGoalUsesLowerEyeAndHitsWithNoExtraLoot(GameTestHelper h){floor(h);var s=mob(h,EntityTypes.SKELETON,8,8);s.getAttached(AbilityState.DATA).putBoolean("baby_choice",true);s.setItemSlot(EquipmentSlot.MAINHAND,Items.BOW.getDefaultInstance());s.getAttribute(Attributes.MOVEMENT_SPEED).setBaseValue(0);s.addTag("buildupmobtweaks:disable_skeleton_weapon_switching");s.addTag("buildupmobtweaks:disable_skeleton_sniping");var t=mob(h,EntityTypes.IRON_GOLEM,8,16);t.setNoAi(true);Set<UUID> ids=new HashSet<>();boolean[] low={false};
        h.onEachTick(()->{for(var a:h.getLevel().getEntitiesOfClass(net.minecraft.world.entity.projectile.arrow.AbstractArrow.class,s.getBoundingBox().inflate(30),a->a.getOwner()==s)){if(ids.add(a.getUUID())&&a.distanceToSqr(s)<4)low[0]|=a.getY()<s.getY()+1.2;}});
        h.runAtTickTime(195,()->{h.assertTrue(s.isBaby()&&low[0]&&ids.size()>=2&&t.getHealth()<1000,"Actual baby native bow Goal releases real low-eye arrows and hits target");s.setDropChance(EquipmentSlot.MAINHAND,0);s.hurtServer(h.getLevel(),s.damageSources().generic(),2000);});
        h.runAtTickTime(220,()->{h.assertTrue(h.getLevel().getEntitiesOfClass(ItemEntity.class,s.getBoundingBox().inflate(6),e->com.davidblackcn.buildupmobtweaks.rebuild.skeleton.SkeletonState.generatedSword(e.getItem())).isEmpty(),"Baby variant never turns generated reserve into a death reward");proof("baby_bow_and_death",s,"lowEye="+low[0]+" arrows="+ids.size()+" targetHP="+t.getHealth());RidingRelationTests.clean(s,t);h.succeed();});}
